import React, { useRef, useState, useEffect, useCallback } from 'react';
import Button from '@mui/material/Button';
import CircularProgress from '@mui/material/CircularProgress';
import Alert from '@mui/material/Alert';
import Card from '@mui/material/Card';
import CardMedia from '@mui/material/CardMedia';
import CardContent from '@mui/material/CardContent';
import Typography from '@mui/material/Typography';
import Stack from '@mui/material/Stack';
import CameraAlt from '@mui/icons-material/CameraAlt';
import Replay from '@mui/icons-material/Replay';
import Videocam from '@mui/icons-material/Videocam';
import VideocamOff from '@mui/icons-material/VideocamOff';
import Box from '@mui/material/Box';

export default function Camera() {
    const videoRef = useRef(null);
    const canvasRef = useRef(null);
    const streamRef = useRef(null);
    const [capturedImage, setCapturedImage] = useState(null);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState(null);
    const [result, setResult] = useState(null);
    const [cameraActive, setCameraActive] = useState(false);

    const startCamera = useCallback(async () => {
        setError(null);
        try {
            const stream = await navigator.mediaDevices.getUserMedia({ video: true });
            streamRef.current = stream;
            if (videoRef.current) {
                videoRef.current.srcObject = stream;
            }
            setCameraActive(true);
        } catch (err) {
            setError('Camera access denied or unavailable.');
        }
    }, []);

    const stopCamera = useCallback(() => {
        if (streamRef.current) {
            streamRef.current.getTracks().forEach(track => track.stop());
            streamRef.current = null;
        }
        setCameraActive(false);
    }, []);

    useEffect(() => {
        startCamera();
        return () => stopCamera();
    }, [startCamera, stopCamera]);

    const capture = () => {
        const video = videoRef.current;
        const canvas = canvasRef.current;
        if (!video || !canvas) return;

        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;
        canvas.getContext('2d').drawImage(video, 0, 0);

        const base64 = canvas.toDataURL('image/jpeg').split(',')[1];
        setCapturedImage(base64);
        setResult(null);
        stopCamera();
    };

    const reset = () => {
        setCapturedImage(null);
        setResult(null);
        setError(null);
        startCamera();
    };

    const recognize = async () => {
        if (!capturedImage) return;
        setLoading(true);
        setError(null);
        setResult(null);

        try {
            const userId = localStorage.getItem('userId') || 1;
            const res = await fetch(`/api/user/${userId}/face`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ image: capturedImage }),
            });

            if (!res.ok) {
                const errData = await res.json();
                throw new Error(errData.error || 'Recognition failed');
            }

            const data = await res.json();
            setResult(data);
        } catch (err) {
            setError(err.message);
        } finally {
            setLoading(false);
        }
    };

    const captureButton = capturedImage ? (
        <Button
            variant="contained"
            onClick={recognize}
            disabled={loading}
            startIcon={loading ? <CircularProgress size={20} color="inherit" /> : <CameraAlt />}
        >
            {loading ? 'Recognizing...' : 'Recognize Face'}
        </Button>
    ) : (
        <Button
            variant="contained"
            onClick={capture}
            startIcon={<CameraAlt />}
        >
            Capture
        </Button>
    );

    return (
        <Box sx={{ p: 3, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 2 }}>
            <Typography variant="h5">Facial Recognition</Typography>

            <canvas ref={canvasRef} style={{ display: 'none' }} />

            {cameraActive && (
                <Card sx={{ maxWidth: 640, width: '100%' }}>
                    <CardMedia
                        component="video"
                        ref={videoRef}
                        autoPlay
                        muted
                        playsInline
                        sx={{ width: '100%' }}
                    />
                </Card>
            )}

            {capturedImage && (
                <Card sx={{ maxWidth: 640, width: '100%' }}>
                    <CardMedia
                        component="img"
                        src={`data:image/jpeg;base64,${capturedImage}`}
                        alt="Captured"
                        sx={{ width: '100%' }}
                    />
                </Card>
            )}

            {error && <Alert severity="error">{error}</Alert>}

            {result && (
                <Card sx={{ maxWidth: 640, width: '100%' }}>
                    <CardContent>
                        <Typography variant="h6">Recognition Result</Typography>
                        <pre style={{ overflow: 'auto', whiteSpace: 'pre-wrap' }}>
                            {JSON.stringify(result, null, 2)}
                        </pre>
                    </CardContent>
                </Card>
            )}

            <Stack direction="row" spacing={2}>
                {cameraActive && captureButton}
                {!cameraActive && !loading && (
                    <>
                        <Button
                            variant="contained"
                            onClick={recognize}
                            disabled={!capturedImage || loading}
                            startIcon={loading ? <CircularProgress size={20} color="inherit" /> : <CameraAlt />}
                        >
                            {loading ? 'Recognizing...' : 'Recognize Face'}
                        </Button>
                        <Button
                            variant="outlined"
                            onClick={reset}
                            startIcon={<Replay />}
                        >
                            Retake
                        </Button>
                    </>
                )}
            </Stack>
        </Box>
    );
}

